package ca.yorku.eecs3311.coursepilot.cli;
import ca.yorku.eecs3311.coursepilot.application.StudyAgentFacade; import org.springframework.stereotype.Component; import picocli.CommandLine.*;
@Component @Command(name="quiz",description="Generate and list grounded quizzes",mixinStandardHelpOptions=true)
public class QuizCommand implements Runnable { private final StudyAgentFacade facade; public QuizCommand(StudyAgentFacade f){facade=f;} public StudyAgentFacade facade(){return facade;} public void run(){System.out.println("Use 'coursepilot quiz generate --help' or 'quiz list --help'.");}
 @Component @Command(name="generate",mixinStandardHelpOptions=true) public static class Generate implements Runnable {private final QuizCommand p; @Option(names="--course",required=true)String course; @Option(names="--document",required=true)Long document; @Option(names="--count",defaultValue="10")Integer count; public Generate(QuizCommand p){this.p=p;} public void run(){var c=p.facade().getCourseByCode(course);var r=p.facade().generateQuiz(c.id(),document,count,java.util.Set.of("MULTIPLE_CHOICE","TRUE_FALSE","SHORT_ANSWER"));System.out.println(r.createdCount()+" quiz questions generated.");}}
 @Component @Command(name="list",mixinStandardHelpOptions=true) public static class ListQuizzes implements Runnable {private final QuizCommand p; @Option(names="--course",required=true)String course; public ListQuizzes(QuizCommand p){this.p=p;} public void run(){var c=p.facade().getCourseByCode(course);p.facade().listQuizzes(c.id()).forEach(q->System.out.printf("%d. %s (%d questions)%n",q.id(),q.title(),q.questions().size()));}}
}
